const items = $input.all().map((item) => item.json);

const topicData = $("Fetch the topic")
  .all()
  .map((item) => item.json)[0];

const updatedItems = items.map((item) => {
  let systemPrompt = item["System Prompt"];
  let userPrompt = item["User Prompt"];

  for (const key in topicData) {
    const regex = new RegExp(`{{${key}}}`, "g");

    systemPrompt = systemPrompt.replace(regex, topicData[key]);
    userPrompt = userPrompt.replace(regex, topicData[key]);
  }

  item["System Prompt"] = systemPrompt;
  item["User Prompt"] = userPrompt;

  return item;
});

return updatedItems;

